  ELSIF OLD.status = 'processing_failed' AND NEW.status = 'processing' THEN
    IF NEW.current_immutable_ref IS DISTINCT FROM OLD.current_immutable_ref OR NEW.current_analysis_revision IS DISTINCT FROM OLD.current_analysis_revision OR NEW.current_terms_revision IS DISTINCT FROM OLD.current_terms_revision OR ROW(NEW.bound_reference_asset_id,NEW.bound_reference_evidence_ref,NEW.bound_reference_audio_revision,NEW.bound_reference_analysis_revision,NEW.bound_reference_audio_sha256,NEW.bound_reference_upstream_share_bps) IS DISTINCT FROM ROW(OLD.bound_reference_asset_id,OLD.bound_reference_evidence_ref,OLD.bound_reference_audio_revision,OLD.bound_reference_analysis_revision,OLD.bound_reference_audio_sha256,OLD.bound_reference_upstream_share_bps) OR NEW.post_id IS DISTINCT FROM OLD.post_id OR NEW.abandonment_reason IS DISTINCT FROM OLD.abandonment_reason OR NEW.retention_disposition IS DISTINCT FROM OLD.retention_disposition THEN RAISE EXCEPTION 'retry transition pointers are not exact'; END IF;
    IF OLD.retryable IS DISTINCT FROM TRUE OR OLD.failure_retry_count IS NULL OR OLD.failure_retry_count >= 3 OR OLD.retry_count >= 3 OR NEW.creation_revision <> OLD.creation_revision + 1 OR NEW.retry_count <> OLD.retry_count + 1 OR NEW.audio_revision <> OLD.audio_revision OR NEW.analysis_revision <> OLD.analysis_revision OR NEW.decision_revision <> 0 OR NEW.current_decision_revision IS NOT NULL OR NEW.workflow_revision <> OLD.workflow_revision OR NEW.phase IS DISTINCT FROM OLD.last_safe_phase OR NEW.failure_code IS NOT NULL OR NEW.failure_retry_count IS NOT NULL OR NEW.retryable IS NOT NULL OR NEW.last_safe_phase IS NOT NULL OR NEW.action_kind IS NOT NULL OR NEW.action_reference_request_ref IS NOT NULL OR NEW.action_expires_at IS NOT NULL OR NEW.review_ref IS NOT NULL OR NEW.review_reason_code IS NOT NULL OR NEW.review_exhaustion_code IS NOT NULL OR NEW.review_exhaustion_attempt_id IS NOT NULL OR NEW.held_revision IS NOT NULL OR NEW.moderator_action_id IS NOT NULL OR NEW.moderator_actor_id IS NOT NULL OR NEW.moderator_evidence_ref IS NOT NULL OR NEW.moderator_approval_kind IS NOT NULL OR NEW.moderator_reason_code IS NOT NULL THEN RAISE EXCEPTION 'retry transition evidence is not exact'; END IF;
  END IF;
  IF NEW.bound_reference_asset_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM media_reference_evidence r WHERE r.community_id = NEW.community_id AND r.actor_user_id = NEW.actor_user_id AND r.submission_id = NEW.submission_id AND r.operation_id = NEW.operation_id AND r.asset_id = NEW.bound_reference_asset_id AND r.evidence_ref = NEW.bound_reference_evidence_ref AND r.evidence_audio_revision = NEW.bound_reference_audio_revision AND r.evidence_analysis_revision = NEW.bound_reference_analysis_revision AND r.evidence_audio_sha256 = NEW.bound_reference_audio_sha256 AND r.upstream_commercial_rev_share_bps IS NOT DISTINCT FROM NEW.bound_reference_upstream_share_bps) THEN RAISE EXCEPTION 'bound reference evidence is missing'; END IF;
  IF (NEW.status = 'processing' AND NEW.phase = 'publish') OR NEW.status = 'published' THEN
    SELECT * INTO analysis_record FROM media_analysis_evidence WHERE community_id=NEW.community_id AND actor_user_id=NEW.actor_user_id AND submission_id = NEW.submission_id AND operation_id=NEW.operation_id AND analysis_revision = NEW.analysis_revision FOR SHARE;
    SELECT * INTO decision_record FROM media_publication_decisions WHERE community_id=NEW.community_id AND actor_user_id=NEW.actor_user_id AND submission_id = NEW.submission_id AND operation_id=NEW.operation_id AND decision_revision = NEW.decision_revision FOR SHARE;
    IF analysis_record.submission_id IS NULL OR decision_record.submission_id IS NULL OR decision_record.outcome <> 'allow' OR decision_record.creation_revision <> NEW.creation_revision OR decision_record.audio_revision <> NEW.audio_revision OR decision_record.analysis_revision <> NEW.analysis_revision OR decision_record.canonical_audio_sha256 <> analysis_record.canonical_audio_sha256 OR analysis_record.media_safety <> 'allow' OR analysis_record.lyrics_safety NOT IN ('skipped', 'allow') OR analysis_record.speech_status = 'unavailable' OR analysis_record.explicitness NOT IN ('not_explicit', 'explicit', 'no_lyrics') OR (analysis_record.acr_decision = 'inconclusive' AND NOT EXISTS (SELECT 1 FROM media_moderation_actions m WHERE m.community_id=NEW.community_id AND m.actor_user_id=NEW.actor_user_id AND m.submission_id=NEW.submission_id AND m.operation_id=NEW.operation_id AND m.action_id=NEW.moderator_action_id AND m.approval_kind='acr_override' AND m.reason_code IN ('acr_inconclusive','acr_exhausted'))) OR (analysis_record.acr_decision = 'skipped' AND NOT EXISTS (SELECT 1 FROM media_moderation_actions m WHERE m.community_id=NEW.community_id AND m.actor_user_id=NEW.actor_user_id AND m.submission_id=NEW.submission_id AND m.operation_id=NEW.operation_id AND m.action_id=NEW.moderator_action_id AND m.approval_kind='acr_override' AND m.reason_code='acr_skipped')) OR (analysis_record.acr_decision = 'requires_reference' AND NEW.bound_reference_asset_id IS NULL) OR NOT EXISTS (SELECT 1 FROM media_submission_terms WHERE community_id=NEW.community_id AND actor_user_id=NEW.actor_user_id AND submission_id = NEW.submission_id AND operation_id=NEW.operation_id AND creation_revision = NEW.creation_revision) THEN RAISE EXCEPTION 'media publication evidence is not ratified'; END IF;
  END IF;
  IF NEW.status = 'published' THEN
    SELECT * INTO post_record FROM posts WHERE community_id = NEW.community_id AND post_id = NEW.post_id FOR SHARE;
    IF post_record.post_id IS NULL OR post_record.author_user_id <> NEW.actor_user_id OR post_record.post_type <> 'song' OR post_record.status <> 'published' OR post_record.visibility <> 'public' OR post_record.title <> NEW.title THEN RAISE EXCEPTION 'media publication Post is not owned by submission'; END IF;
  END IF;
  IF NEW.status = 'abandoned' AND NEW.abandonment_reason = 'reservation_expired' AND NOT EXISTS (SELECT 1 FROM media_upload_reservations r WHERE r.community_id=NEW.community_id AND r.actor_user_id=NEW.actor_user_id AND r.reservation_id=NEW.audio_reservation_id AND r.expires_at <= clock_timestamp()) THEN RAISE EXCEPTION 'reservation is not expired'; END IF;
  IF NEW.status = 'abandoned' AND NEW.abandonment_reason IN ('author_cancelled', 'reservation_expired') AND NEW.retention_disposition IS DISTINCT FROM 'no_object' THEN RAISE EXCEPTION 'pre-finalize abandonment retention is not exact'; END IF;
  IF NEW.status = 'abandoned' AND NEW.abandonment_reason IN ('upload_expectation_mismatch', 'upload_source_changed_before_finalize') AND NEW.retention_disposition IS DISTINCT FROM 'retain_for_reconciliation' THEN RAISE EXCEPTION 'upload precondition abandonment retention is not exact'; END IF;
  IF NEW.status = 'abandoned' AND NEW.abandonment_reason = 'action_deadline_elapsed' AND NEW.retention_disposition IS DISTINCT FROM (CASE WHEN NEW.audio_revision > 0 THEN 'retain_until_expiry' ELSE 'no_object' END) THEN RAISE EXCEPTION 'action deadline retention is not exact'; END IF;
  IF NEW.status = 'abandoned' THEN
    IF NEW.phase IS NOT NULL OR NEW.post_id IS NOT NULL OR NEW.audio_revision IS DISTINCT FROM OLD.audio_revision OR NEW.analysis_revision IS DISTINCT FROM OLD.analysis_revision OR NEW.decision_revision <> 0 OR NEW.current_decision_revision IS NOT NULL OR NEW.current_immutable_ref IS DISTINCT FROM OLD.current_immutable_ref OR NEW.current_analysis_revision IS DISTINCT FROM OLD.current_analysis_revision OR NEW.current_terms_revision IS DISTINCT FROM OLD.current_terms_revision OR ROW(NEW.bound_reference_asset_id, NEW.bound_reference_evidence_ref, NEW.bound_reference_audio_revision, NEW.bound_reference_analysis_revision, NEW.bound_reference_audio_sha256, NEW.bound_reference_upstream_share_bps) IS DISTINCT FROM ROW(OLD.bound_reference_asset_id, OLD.bound_reference_evidence_ref, OLD.bound_reference_audio_revision, OLD.bound_reference_analysis_revision, OLD.bound_reference_audio_sha256, OLD.bound_reference_upstream_share_bps) OR NEW.workflow_revision <> OLD.workflow_revision OR NEW.retry_count <> OLD.retry_count OR NEW.failure_code IS NOT NULL OR NEW.failure_retry_count IS NOT NULL OR NEW.retryable IS NOT NULL OR NEW.last_safe_phase IS NOT NULL OR NEW.action_kind IS NOT NULL OR NEW.action_reference_request_ref IS NOT NULL OR NEW.action_expires_at IS NOT NULL OR NEW.review_ref IS NOT NULL OR NEW.review_reason_code IS NOT NULL OR NEW.review_exhaustion_code IS NOT NULL OR NEW.review_exhaustion_attempt_id IS NOT NULL OR NEW.held_revision IS NOT NULL OR NEW.moderator_action_id IS NOT NULL OR NEW.moderator_actor_id IS NOT NULL OR NEW.moderator_evidence_ref IS NOT NULL OR NEW.moderator_approval_kind IS NOT NULL OR NEW.moderator_reason_code IS NOT NULL THEN RAISE EXCEPTION 'abandoned cleanup is not exact'; END IF;
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_megapot_allocation_batch_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Megapot allocation batches cannot be deleted';
  END IF;
  IF TG_OP = 'UPDATE' AND (
    ROW(
      NEW.allocation_batch_id, NEW.pool_leg_id, NEW.drawing_id, NEW.snapshot_id,
      NEW.claim_effect_id, NEW.algorithm_version, NEW.net_winnings_atomic,
      NEW.allocation_count, NEW.allocation_hash, NEW.created_at
    ) IS DISTINCT FROM ROW(
      OLD.allocation_batch_id, OLD.pool_leg_id, OLD.drawing_id, OLD.snapshot_id,
      OLD.claim_effect_id, OLD.algorithm_version, OLD.net_winnings_atomic,
      OLD.allocation_count, OLD.allocation_hash, OLD.created_at
    ) OR OLD.state <> 'prepared' OR NEW.state <> 'credited'
  ) THEN
    RAISE EXCEPTION 'invalid Megapot allocation batch transition';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_megapot_attestation_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Megapot deployment attestations cannot be deleted';
  END IF;
  IF ROW(
    NEW.attestation_id, NEW.environment, NEW.chain_id, NEW.jackpot_address,
    NEW.usdc_address, NEW.ticket_nft_address, NEW.custody_address,
    NEW.referrer_address, NEW.source_tag, NEW.jackpot_code_hash,
    NEW.usdc_code_hash, NEW.ticket_nft_code_hash, NEW.attestation_block_number,
    NEW.attestation_block_hash, NEW.abi_version, NEW.verified_at, NEW.created_at
  ) IS DISTINCT FROM ROW(
    OLD.attestation_id, OLD.environment, OLD.chain_id, OLD.jackpot_address,
    OLD.usdc_address, OLD.ticket_nft_address, OLD.custody_address,
    OLD.referrer_address, OLD.source_tag, OLD.jackpot_code_hash,
    OLD.usdc_code_hash, OLD.ticket_nft_code_hash, OLD.attestation_block_number,
    OLD.attestation_block_hash, OLD.abi_version, OLD.verified_at, OLD.created_at
  ) OR OLD.status <> 'active' OR NEW.status <> 'retired' THEN
    RAISE EXCEPTION 'Megapot deployment attestation only permits retirement';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_megapot_claim_effect() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  chain_record reward_chain_effects%ROWTYPE;
  attestation_record megapot_deployment_attestations%ROWTYPE;
  ticket_record megapot_ticket_inventory%ROWTYPE;
  sweep_record megapot_drawing_sweeps%ROWTYPE;
  sweep_evidence megapot_sweep_ticket_evidence%ROWTYPE;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'Megapot claim effects are append-only';
  END IF;
  SELECT * INTO chain_record FROM reward_chain_effects
   WHERE effect_id = NEW.claim_effect_id FOR SHARE;
  SELECT * INTO attestation_record FROM megapot_deployment_attestations
   WHERE attestation_id = NEW.attestation_id FOR SHARE;
  SELECT * INTO ticket_record FROM megapot_ticket_inventory
   WHERE attestation_id = NEW.attestation_id AND ticket_id = NEW.ticket_id FOR SHARE;
  SELECT * INTO sweep_record FROM megapot_drawing_sweeps
   WHERE sweep_id = NEW.sweep_id FOR SHARE;
  SELECT * INTO sweep_evidence FROM megapot_sweep_ticket_evidence
   WHERE sweep_id = NEW.sweep_id AND ticket_id = NEW.ticket_id FOR SHARE;
  IF chain_record.effect_kind <> 'winnings_claim'
     OR chain_record.chain_id <> attestation_record.chain_id
     OR chain_record.signer_address <> attestation_record.custody_address
     OR chain_record.target_address <> attestation_record.jackpot_address
     OR ticket_record.pool_leg_id <> NEW.pool_leg_id
     OR ticket_record.drawing_id <> NEW.drawing_id
     OR ticket_record.status <> 'claim_pending'
     OR sweep_record.state <> 'complete'
     OR sweep_record.pool_leg_id <> NEW.pool_leg_id
     OR sweep_record.drawing_id <> NEW.drawing_id
     OR sweep_evidence.attestation_id <> NEW.attestation_id
     OR sweep_evidence.tier_id IN (0, 2)
     OR sweep_evidence.gross_winnings_atomic <> NEW.expected_gross_winnings_atomic
     OR sweep_evidence.net_winnings_atomic <> NEW.expected_net_winnings_atomic
     OR sweep_evidence.referral_accrual_atomic <>
          NEW.expected_referral_accrual_atomic THEN
    RAISE EXCEPTION 'Megapot claim effect does not match custody ticket';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_megapot_claim_effect_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  chain_record reward_chain_effects%ROWTYPE;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Megapot claim effects cannot be deleted';
  END IF;
  IF TG_OP = 'UPDATE' THEN
    IF ROW(
      NEW.claim_effect_id, NEW.attestation_id, NEW.ticket_id, NEW.pool_leg_id,
      NEW.drawing_id, NEW.sweep_id, NEW.expected_gross_winnings_atomic,
      NEW.expected_net_winnings_atomic, NEW.expected_referral_accrual_atomic,
      NEW.custody_balance_before_atomic, NEW.referral_balance_before_atomic,
      NEW.preflight_block_number, NEW.preflight_block_hash, NEW.created_at
    ) IS DISTINCT FROM ROW(
      OLD.claim_effect_id, OLD.attestation_id, OLD.ticket_id, OLD.pool_leg_id,
      OLD.drawing_id, OLD.sweep_id, OLD.expected_gross_winnings_atomic,
      OLD.expected_net_winnings_atomic, OLD.expected_referral_accrual_atomic,
      OLD.custody_balance_before_atomic, OLD.referral_balance_before_atomic,
      OLD.preflight_block_number, OLD.preflight_block_hash, OLD.created_at
    ) OR OLD.received_atomic IS NOT NULL OR OLD.referral_accrual_atomic IS NOT NULL
       OR OLD.claim_log_index IS NOT NULL OR OLD.burn_log_index IS NOT NULL
       OR OLD.referral_log_index IS NOT NULL OR OLD.transfer_log_index IS NOT NULL
       OR NEW.received_atomic IS NULL OR NEW.referral_accrual_atomic IS NULL
       OR NEW.claim_log_index IS NULL OR NEW.burn_log_index IS NULL
       OR NEW.referral_log_index IS NULL OR NEW.transfer_log_index IS NULL THEN
      RAISE EXCEPTION 'invalid Megapot claim observation update';
    END IF;
    SELECT * INTO chain_record FROM reward_chain_effects
     WHERE effect_id = NEW.claim_effect_id FOR SHARE;
    IF chain_record.state <> 'confirmed'
       OR chain_record.settled_amount_atomic <> NEW.received_atomic THEN
      RAISE EXCEPTION 'Megapot claim observation requires confirmed exact receipt';
    END IF;
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_megapot_commitment_effect() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Megapot commitment effects cannot be deleted';
  END IF;
  IF TG_OP = 'UPDATE' THEN
    IF ROW(
      NEW.commitment_effect_id, NEW.snapshot_id, NEW.payload_hash,
      NEW.signing_key_id, NEW.signature, NEW.prepared_at, NEW.created_at
    ) IS DISTINCT FROM ROW(
      OLD.commitment_effect_id, OLD.snapshot_id, OLD.payload_hash,
      OLD.signing_key_id, OLD.signature, OLD.prepared_at, OLD.created_at
    ) OR OLD.state <> 'prepared' OR NEW.state <> 'published' THEN
      RAISE EXCEPTION 'invalid Megapot commitment publication';
    END IF;
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_megapot_drawing_sweep() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Megapot drawing sweeps cannot be deleted';
  END IF;
  IF TG_OP = 'UPDATE' AND (
    ROW(
      NEW.sweep_id, NEW.pool_leg_id, NEW.attestation_id, NEW.drawing_id,
      NEW.observation_block_number, NEW.observation_block_hash,
      NEW.drawing_state_hash, NEW.ticket_count, NEW.winning_ticket_count,
      NEW.observed_at, NEW.created_at
    ) IS DISTINCT FROM ROW(
      OLD.sweep_id, OLD.pool_leg_id, OLD.attestation_id, OLD.drawing_id,
      OLD.observation_block_number, OLD.observation_block_hash,
      OLD.drawing_state_hash, OLD.ticket_count, OLD.winning_ticket_count,
      OLD.observed_at, OLD.created_at
    ) OR OLD.state <> 'observed'
       OR NEW.state NOT IN ('complete', 'reconciliation_required')
  ) THEN
    RAISE EXCEPTION 'invalid Megapot drawing sweep transition';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_megapot_pool_drawing() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  leg_record song_reward_offer_legs%ROWTYPE;
  observation_record megapot_drawing_observations%ROWTYPE;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Megapot pool drawings cannot be deleted';
  END IF;
  IF TG_OP = 'INSERT' THEN
    SELECT * INTO leg_record FROM song_reward_offer_legs
     WHERE leg_id = NEW.pool_leg_id FOR SHARE;
    SELECT * INTO observation_record FROM megapot_drawing_observations
     WHERE observation_id = NEW.observation_id FOR SHARE;
    IF NEW.status <> 'entry_open' OR leg_record.kind <> 'megapot_pool'
       OR leg_record.status <> 'active'
       OR NEW.drawing_id < leg_record.participation_starts_drawing_id
       OR observation_record.observation_id IS NULL
       OR observation_record.attestation_id <> leg_record.attestation_id
       OR observation_record.drawing_id <> NEW.drawing_id
       OR observation_record.drawing_locked
       OR observation_record.expires_at <= clock_timestamp()
       OR NEW.entry_cutoff_at <> observation_record.drawing_time
            - make_interval(secs => leg_record.entry_cutoff_seconds)
       OR NEW.ticket_price_ceiling_atomic <> leg_record.max_ticket_price_atomic THEN
      RAISE EXCEPTION 'Megapot pool drawing does not match live leg and observation';
    END IF;
    RETURN NEW;
  END IF;
  IF ROW(
    NEW.pool_leg_id, NEW.drawing_id, NEW.observation_id, NEW.entry_cutoff_at,
    NEW.ticket_price_ceiling_atomic, NEW.created_at
  ) IS DISTINCT FROM ROW(
    OLD.pool_leg_id, OLD.drawing_id, OLD.observation_id, OLD.entry_cutoff_at,
    OLD.ticket_price_ceiling_atomic, OLD.created_at
  ) THEN
    RAISE EXCEPTION 'Megapot pool drawing identity is immutable';
  END IF;
  IF OLD.status IN (
    'no_win', 'credited', 'closed_no_entries', 'closed_unfunded',
    'closed_fallback_ineligible', 'closed_fallback_unavailable',
    'closed_fallback_ceiling', 'operational_hold'
  ) AND NEW IS DISTINCT FROM OLD THEN
    RAISE EXCEPTION 'terminal Megapot pool drawing is immutable';
  END IF;
  IF NEW.version <> OLD.version + 1 OR NEW.updated_at <= OLD.updated_at THEN
    RAISE EXCEPTION 'Megapot pool drawing transition requires next version and time';
  END IF;
  IF NOT (
    (OLD.status = 'entry_open' AND NEW.status IN (
      'cutoff_frozen', 'closed_no_entries', 'closed_unfunded',
      'closed_fallback_ineligible', 'closed_fallback_unavailable',
      'closed_fallback_ceiling', 'operational_hold'
    ))
    OR (OLD.status = 'cutoff_frozen' AND NEW.status IN ('committed', 'operational_hold'))
    OR (OLD.status = 'committed' AND NEW.status IN ('purchase_pending', 'operational_hold'))
    OR (OLD.status = 'purchase_pending' AND NEW.status IN ('tickets_confirmed', 'operational_hold'))
    OR (OLD.status = 'tickets_confirmed' AND NEW.status IN ('drawing_pending', 'operational_hold'))
    OR (OLD.status = 'drawing_pending' AND NEW.status IN (
      'no_win', 'winnings_detected', 'operational_hold'
    ))
    OR (OLD.status = 'winnings_detected' AND NEW.status IN ('claim_pending', 'operational_hold'))
    OR (OLD.status = 'claim_pending' AND NEW.status IN ('claimed', 'operational_hold'))
    OR (OLD.status = 'claimed' AND NEW.status IN ('allocated', 'operational_hold'))
    OR (OLD.status = 'allocated' AND NEW.status IN ('credited', 'operational_hold'))
  ) THEN
    RAISE EXCEPTION 'invalid Megapot pool drawing transition';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_megapot_pool_share() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  drawing_record megapot_pool_drawings%ROWTYPE;
  leg_record song_reward_offer_legs%ROWTYPE;
  offer_record song_reward_offers%ROWTYPE;
  qualification_record activity_qualifications%ROWTYPE;
  eligibility_record reward_eligibility_decisions%ROWTYPE;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'Megapot pool shares are append-only';
  END IF;
  SELECT * INTO drawing_record FROM megapot_pool_drawings
   WHERE pool_leg_id = NEW.pool_leg_id AND drawing_id = NEW.drawing_id FOR UPDATE;
  SELECT * INTO leg_record FROM song_reward_offer_legs
   WHERE leg_id = NEW.pool_leg_id FOR SHARE;
  SELECT * INTO offer_record FROM song_reward_offers
   WHERE offer_id = leg_record.offer_id FOR SHARE;
  SELECT * INTO qualification_record FROM activity_qualifications
   WHERE qualification_id = NEW.qualification_id FOR SHARE;
  SELECT * INTO eligibility_record FROM reward_eligibility_decisions
   WHERE eligibility_decision_id = NEW.eligibility_decision_id FOR SHARE;
  IF drawing_record.status <> 'entry_open'
     OR clock_timestamp() >= drawing_record.entry_cutoff_at
     OR qualification_record.account_id <> NEW.account_id
     OR qualification_record.persona_id <> NEW.persona_id
     OR qualification_record.community_id <> offer_record.community_id
     OR qualification_record.post_id <> offer_record.post_id
     OR qualification_record.audio_revision <> offer_record.audio_revision
     OR NOT qualification_record.activity_key = ANY(leg_record.eligible_activities)
     OR qualification_record.score_bps < leg_record.min_score_bps
     OR qualification_record.qualified_at >= drawing_record.entry_cutoff_at
     OR qualification_record.qualified_at < leg_record.participation_starts_at
     OR NEW.qualified_at <> qualification_record.qualified_at
     OR eligibility_record.leg_id <> NEW.pool_leg_id
     OR eligibility_record.account_id <> NEW.account_id
     OR eligibility_record.persona_id <> NEW.persona_id
     OR eligibility_record.purpose <> 'pool_share'
     OR eligibility_record.qualification_id <> NEW.qualification_id
     OR eligibility_record.drawing_id <> NEW.drawing_id
     OR eligibility_record.outcome <> 'eligible'
     OR eligibility_record.expires_at <= clock_timestamp() THEN
    RAISE EXCEPTION 'Megapot pool share is not exact eligible qualification output';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_megapot_purchase_effect() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  chain_record reward_chain_effects%ROWTYPE;
  attestation_record megapot_deployment_attestations%ROWTYPE;
  observation_record megapot_drawing_observations%ROWTYPE;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'Megapot purchase effects are append-only';
  END IF;
  SELECT * INTO chain_record FROM reward_chain_effects
   WHERE effect_id = NEW.purchase_effect_id FOR SHARE;
  SELECT * INTO attestation_record FROM megapot_deployment_attestations
   WHERE attestation_id = NEW.attestation_id FOR SHARE;
  SELECT * INTO observation_record FROM megapot_drawing_observations
   WHERE observation_id = NEW.drawing_observation_id FOR SHARE;
  IF chain_record.effect_kind <> 'ticket_purchase'
     OR chain_record.chain_id <> attestation_record.chain_id
     OR chain_record.signer_address <> attestation_record.custody_address
     OR chain_record.target_address <> attestation_record.jackpot_address
     OR chain_record.reserved_amount_atomic <> NEW.ticket_price_atomic
     OR NEW.recipient_address <> attestation_record.custody_address
     OR NEW.source_tag <> attestation_record.source_tag
     OR observation_record.attestation_id <> NEW.attestation_id
     OR observation_record.drawing_id <> NEW.drawing_id
     OR observation_record.ticket_price_atomic <> NEW.ticket_price_atomic
     OR NEW.normal_five > observation_record.ball_max
     OR NEW.bonusball > observation_record.bonusball_max THEN
    RAISE EXCEPTION 'Megapot purchase effect does not match deployment and drawing';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_megapot_ticket_inventory() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  purchase_record megapot_ticket_purchase_effects%ROWTYPE;
  chain_record reward_chain_effects%ROWTYPE;
  attestation_record megapot_deployment_attestations%ROWTYPE;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Megapot ticket inventory cannot be deleted';
  END IF;
  IF TG_OP = 'INSERT' THEN
    SELECT * INTO purchase_record FROM megapot_ticket_purchase_effects
     WHERE purchase_effect_id = NEW.purchase_effect_id FOR SHARE;
    SELECT * INTO chain_record FROM reward_chain_effects
     WHERE effect_id = NEW.purchase_effect_id FOR SHARE;
    SELECT * INTO attestation_record FROM megapot_deployment_attestations
     WHERE attestation_id = NEW.attestation_id FOR SHARE;
    IF chain_record.state <> 'confirmed' OR chain_record.receipt_status <> 'success'
       OR chain_record.transaction_hash <> NEW.minted_transaction_hash
       OR purchase_record.pool_leg_id <> NEW.pool_leg_id
       OR purchase_record.drawing_id <> NEW.drawing_id
       OR purchase_record.attestation_id <> NEW.attestation_id
       OR NEW.custody_address <> attestation_record.custody_address
       OR NEW.status <> 'custodied' THEN
      RAISE EXCEPTION 'Megapot ticket inventory requires confirmed custody mint';
    END IF;
    RETURN NEW;
  END IF;
  IF ROW(
    NEW.attestation_id, NEW.ticket_id, NEW.purchase_effect_id,
    NEW.pool_leg_id, NEW.drawing_id, NEW.custody_address,
    NEW.owner_observation_block_number, NEW.owner_observation_block_hash,
    NEW.minted_transaction_hash, NEW.minted_log_index, NEW.acquired_at
  ) IS DISTINCT FROM ROW(
    OLD.attestation_id, OLD.ticket_id, OLD.purchase_effect_id,
    OLD.pool_leg_id, OLD.drawing_id, OLD.custody_address,
    OLD.owner_observation_block_number, OLD.owner_observation_block_hash,
    OLD.minted_transaction_hash, OLD.minted_log_index, OLD.acquired_at
  ) THEN
    RAISE EXCEPTION 'Megapot ticket inventory identity is immutable';
  END IF;
  IF NOT (
    (OLD.status = 'custodied' AND NEW.status IN ('claim_pending', 'no_win'))
    OR (OLD.status = 'claim_pending' AND NEW.status = 'claimed')
  ) THEN
    RAISE EXCEPTION 'invalid Megapot ticket inventory transition';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_megapot_usdc_approval_effect() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  chain_record reward_chain_effects%ROWTYPE;
  attestation_record megapot_deployment_attestations%ROWTYPE;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'Megapot USDC approval effects are append-only';
  END IF;
  SELECT * INTO chain_record FROM reward_chain_effects
   WHERE effect_id = NEW.approval_effect_id FOR SHARE;
  SELECT * INTO attestation_record FROM megapot_deployment_attestations
   WHERE attestation_id = NEW.attestation_id FOR SHARE;
  IF chain_record.effect_kind <> 'usdc_approval'
     OR chain_record.chain_id <> attestation_record.chain_id
     OR chain_record.signer_address <> attestation_record.custody_address
     OR chain_record.target_address <> attestation_record.usdc_address
     OR chain_record.reserved_amount_atomic <> 0
     OR NEW.spender_address <> attestation_record.jackpot_address THEN
    RAISE EXCEPTION 'Megapot USDC approval effect does not match deployment';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_megapot_usdc_approval_receipt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  chain_record reward_chain_effects%ROWTYPE;
  approval_record megapot_usdc_approval_effects%ROWTYPE;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'Megapot USDC approval receipt evidence is append-only';
  END IF;
  SELECT * INTO chain_record FROM reward_chain_effects
   WHERE effect_id = NEW.approval_effect_id FOR SHARE;
  SELECT * INTO approval_record FROM megapot_usdc_approval_effects
   WHERE approval_effect_id = NEW.approval_effect_id FOR SHARE;
  IF chain_record.state <> 'confirmed'
     OR chain_record.receipt_status <> 'success'
     OR chain_record.transaction_hash <> NEW.transaction_hash
     OR chain_record.receipt_block_number <> NEW.block_number
     OR chain_record.receipt_block_hash <> NEW.block_hash
     OR chain_record.receipt_hash <> NEW.receipt_hash
     OR chain_record.confirmations <> NEW.confirmations
     OR approval_record.attestation_id <> NEW.attestation_id
     OR approval_record.approved_amount_atomic <> NEW.approved_amount_atomic
     OR NEW.allowance_after_atomic < approval_record.minimum_allowance_atomic THEN
    RAISE EXCEPTION 'Megapot USDC approval receipt does not prove allowance';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_namespace_ownership_completion_attempt_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  session_record namespace_ownership_sessions%ROWTYPE;
  intent_record community_creation_intents%ROWTYPE;
  state_record community_creation_requirement_states%ROWTYPE;
  transition_at TIMESTAMPTZ;
BEGIN
  transition_at := clock_timestamp();
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'namespace ownership completion attempts are append-only';
  END IF;

  IF TG_OP = 'INSERT' THEN
    NEW.created_at := transition_at;
    NEW.updated_at := transition_at;
    PERFORM 1 FROM users WHERE user_id = NEW.actor_id FOR SHARE;
    SELECT ci.* INTO intent_record
      FROM community_creation_intents AS ci
     WHERE ci.actor_id = NEW.actor_id
       AND ci.intent_id = (
         SELECT ns0.creation_intent_id
           FROM namespace_ownership_sessions AS ns0
          WHERE ns0.namespace_session_id = NEW.namespace_session_id
            AND ns0.actor_id = NEW.actor_id
       )
     FOR SHARE;
    SELECT crs.* INTO state_record
      FROM community_creation_requirement_states AS crs
     WHERE crs.actor_id = NEW.actor_id
       AND crs.intent_id = intent_record.intent_id
       AND crs.requirement_kind = 'namespace_ownership'
     FOR SHARE;
    SELECT ns.* INTO session_record
      FROM namespace_ownership_sessions AS ns
     WHERE ns.namespace_session_id = NEW.namespace_session_id
       AND ns.actor_id = NEW.actor_id
     FOR UPDATE;
    IF session_record.namespace_session_id IS NULL
      OR intent_record.intent_id IS NULL
      OR state_record.intent_id IS NULL
      OR session_record.status <> 'pending'
      OR session_record.expires_at <= transition_at
      OR NEW.state <> 'leased'
      OR NEW.consumption_kind IS NOT NULL
      OR NEW.fence_token <> 1
      OR NEW.lease_expires_at <= transition_at
    THEN
      RAISE EXCEPTION 'namespace ownership completion attempt requires a live pending session';
    END IF;
    IF NEW.lease_expires_at > session_record.expires_at THEN
      RAISE EXCEPTION 'completion lease exceeds its namespace session expiry';
    END IF;
    RETURN NEW;
  END IF;

  IF ROW(
    NEW.completion_attempt_id, NEW.namespace_session_id, NEW.actor_id,
    NEW.idempotency_key, NEW.completion_request_hash, NEW.evidence_ref,
    NEW.submission_channel, NEW.created_at
  ) IS DISTINCT FROM ROW(
    OLD.completion_attempt_id, OLD.namespace_session_id, OLD.actor_id,
    OLD.idempotency_key, OLD.completion_request_hash, OLD.evidence_ref,
    OLD.submission_channel, OLD.created_at
  ) THEN
    RAISE EXCEPTION 'namespace ownership completion attempt identity is immutable';
  END IF;

  IF OLD.state = NEW.state
    AND OLD.fence_token = NEW.fence_token
    AND OLD.lease_expires_at = NEW.lease_expires_at
    AND OLD.consumption_kind IS NOT DISTINCT FROM NEW.consumption_kind
    AND OLD.updated_at = NEW.updated_at
  THEN
    RETURN NEW;
  END IF;

  SELECT * INTO session_record
    FROM namespace_ownership_sessions
   WHERE namespace_session_id = NEW.namespace_session_id
     AND actor_id = NEW.actor_id;
  IF session_record.namespace_session_id IS NULL
    OR session_record.status NOT IN ('pending', 'expired')
  THEN
    RAISE EXCEPTION 'completion attempt requires its pending or expired session';
  END IF;

  IF OLD.state = 'leased'
    AND NEW.state = 'released'
    AND NEW.fence_token = OLD.fence_token
    AND NEW.lease_expires_at = OLD.lease_expires_at
    AND NEW.consumption_kind IS NULL
  THEN
    IF session_record.status = 'pending'
      AND session_record.expires_at > transition_at
    THEN
      NEW.updated_at := transition_at;
      RETURN NEW;
    END IF;
    RETURN NULL;
  END IF;

  IF OLD.state = 'leased'
    AND NEW.state = 'consumed'
    AND NEW.fence_token = OLD.fence_token
    AND NEW.lease_expires_at = OLD.lease_expires_at
    AND OLD.consumption_kind IS NULL
  THEN
    IF NEW.consumption_kind IN ('semantic_contradiction', 'verified', 'rejected') THEN
      IF session_record.status = 'pending'
        AND OLD.lease_expires_at > transition_at
        AND session_record.expires_at > transition_at
      THEN
        NEW.updated_at := transition_at;
        RETURN NEW;
      END IF;
      RETURN NULL;
    END IF;
    IF NEW.consumption_kind = 'expired' THEN
      IF session_record.status IN ('pending', 'expired')
        AND session_record.expires_at <= transition_at
      THEN
        NEW.updated_at := transition_at;
        RETURN NEW;
      END IF;
      RETURN NULL;
    END IF;
  END IF;

  IF OLD.state IN ('released', 'leased')
    AND NEW.state = 'leased'
    AND NEW.fence_token = OLD.fence_token + 1
    AND NEW.lease_expires_at <= session_record.expires_at
    AND NEW.consumption_kind IS NULL
  THEN
    IF session_record.status = 'pending'
      AND session_record.expires_at > transition_at
      AND NEW.lease_expires_at > transition_at
      AND (
        OLD.state = 'released'
        OR OLD.lease_expires_at <= transition_at
      )
    THEN
      NEW.updated_at := transition_at;
      RETURN NEW;
    END IF;
    RETURN NULL;
  END IF;

  RAISE EXCEPTION 'namespace ownership completion attempt transition is not allowed: % -> %',
    OLD.state, NEW.state;
END;
$$;

CREATE FUNCTION guard_namespace_ownership_session_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'namespace ownership sessions are append-only';
  END IF;

  IF ROW(
    NEW.namespace_session_id, NEW.actor_id, NEW.creation_intent_id,
    NEW.ceremony_intent_id, NEW.start_reservation_id, NEW.start_fence_token,
    NEW.expected_revision, NEW.requirement_kind, NEW.generation,
    NEW.requirement_hash, NEW.request_hash, NEW.provider_id,
    NEW.provider_binding_hash, NEW.provider_configuration_kind,
    NEW.provider_configuration_ref, NEW.provider_configuration_version,
    NEW.protocol_version, NEW.environment, NEW.route_family,
    NEW.route_root_label, NEW.route_root_label_display, NEW.route_path_segment,
    NEW.route_href, NEW.route_app_host, NEW.upstream_session_ref,
    NEW.presentation_kind, NEW.presentation_payload, NEW.started_at, NEW.expires_at,
    NEW.created_at
  ) IS DISTINCT FROM ROW(
    OLD.namespace_session_id, OLD.actor_id, OLD.creation_intent_id,
    OLD.ceremony_intent_id, OLD.start_reservation_id, OLD.start_fence_token,
    OLD.expected_revision, OLD.requirement_kind, OLD.generation,
    OLD.requirement_hash, OLD.request_hash, OLD.provider_id,
    OLD.provider_binding_hash, OLD.provider_configuration_kind,
    OLD.provider_configuration_ref, OLD.provider_configuration_version,
    OLD.protocol_version, OLD.environment, OLD.route_family,
    OLD.route_root_label, OLD.route_root_label_display, OLD.route_path_segment,
    OLD.route_href, OLD.route_app_host, OLD.upstream_session_ref,
    OLD.presentation_kind, OLD.presentation_payload, OLD.started_at, OLD.expires_at,
    OLD.created_at
  ) THEN
    RAISE EXCEPTION 'namespace ownership session identity and launch fields are immutable';
  END IF;

  IF NOT (
    OLD.status = 'pending'
    AND NEW.status IN ('completed', 'failed', 'expired')
    AND NEW.generation = OLD.generation
  ) THEN
    RAISE EXCEPTION 'namespace ownership session transition is not allowed: % -> %',
      OLD.status, NEW.status;
  END IF;

  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_namespace_ownership_start_reservation_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  intent_record community_creation_intents%ROWTYPE;
  state_record community_creation_requirement_states%ROWTYPE;
  ceremony_record community_creation_ceremony_attempts%ROWTYPE;
  session_record namespace_ownership_sessions%ROWTYPE;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'namespace ownership start reservations are append-only';
  END IF;

  IF TG_OP = 'INSERT' THEN
    -- Lock order: actor -> intent -> requirement state -> start reservation.
    PERFORM 1 FROM users WHERE user_id = NEW.actor_id FOR SHARE;
    SELECT * INTO intent_record
      FROM community_creation_intents
     WHERE actor_id = NEW.actor_id AND intent_id = NEW.creation_intent_id
     FOR SHARE;
    SELECT * INTO state_record
      FROM community_creation_requirement_states
     WHERE actor_id = NEW.actor_id
       AND intent_id = NEW.creation_intent_id
       AND requirement_kind = NEW.requirement_kind
     FOR UPDATE;
    SELECT * INTO ceremony_record
      FROM community_creation_ceremony_attempts
     WHERE actor_id = NEW.actor_id
       AND intent_id = NEW.creation_intent_id
       AND requirement_kind = NEW.requirement_kind
       AND generation = NEW.generation
       AND ceremony_intent_id = NEW.ceremony_intent_id
     FOR SHARE;
    SELECT * INTO session_record
      FROM namespace_ownership_sessions
     WHERE namespace_session_id = NEW.namespace_session_id
       AND actor_id = NEW.actor_id
     FOR SHARE;

    IF intent_record.intent_id IS NULL
      OR state_record.intent_id IS NULL
      OR ceremony_record.ceremony_intent_id IS NULL
      OR state_record.status <> 'pending'
      OR intent_record.revision <> NEW.expected_revision
      OR state_record.current_ceremony_intent_id <> NEW.ceremony_intent_id
      OR state_record.generation <> NEW.generation
      OR state_record.requirement_hash <> NEW.requirement_hash
      OR state_record.provider_id <> NEW.provider_id
      OR state_record.provider_binding_hash <> NEW.provider_binding_hash
      OR state_record.provider_configuration_kind <> NEW.provider_configuration_kind
      OR state_record.provider_configuration_ref <> NEW.provider_configuration_ref
      OR state_record.provider_configuration_version <> NEW.provider_configuration_version
      OR state_record.route_family <> NEW.route_family
      OR state_record.route_root_label <> NEW.route_root_label
      OR state_record.route_root_label_display <> NEW.route_root_label_display
      OR state_record.route_path_segment <> NEW.route_path_segment
      OR ceremony_record.requirement_hash <> NEW.requirement_hash
      OR ceremony_record.provider_id <> NEW.provider_id
      OR ceremony_record.provider_binding_hash <> NEW.provider_binding_hash
      OR ceremony_record.provider_configuration_kind <> NEW.provider_configuration_kind
      OR ceremony_record.provider_configuration_ref <> NEW.provider_configuration_ref
      OR ceremony_record.provider_configuration_version <> NEW.provider_configuration_version
      OR ceremony_record.route_family IS DISTINCT FROM NEW.route_family
      OR ceremony_record.route_root_label IS DISTINCT FROM NEW.route_root_label
      OR ceremony_record.route_root_label_display IS DISTINCT FROM NEW.route_root_label_display
      OR ceremony_record.route_path_segment IS DISTINCT FROM NEW.route_path_segment
      OR NEW.state <> 'acquired'
      OR NEW.fence_token <> 1
      OR NEW.lease_expires_at <= clock_timestamp()
      OR (
        session_record.namespace_session_id IS NOT NULL
        AND NEW.lease_expires_at > session_record.expires_at
      )
    THEN
      RAISE EXCEPTION 'namespace ownership start reservation does not match its ceremony';
    END IF;

    IF session_record.namespace_session_id IS NOT NULL
      AND (
        session_record.start_reservation_id <> NEW.reservation_id
        OR session_record.start_fence_token <> NEW.fence_token
        OR session_record.expected_revision <> NEW.expected_revision
        OR session_record.requirement_hash <> NEW.requirement_hash
        OR session_record.request_hash <> NEW.request_hash
        OR session_record.provider_id <> NEW.provider_id
        OR session_record.provider_binding_hash <> NEW.provider_binding_hash
        OR session_record.provider_configuration_kind <> NEW.provider_configuration_kind
        OR session_record.provider_configuration_ref <> NEW.provider_configuration_ref
        OR session_record.provider_configuration_version <> NEW.provider_configuration_version
        OR session_record.protocol_version <> NEW.protocol_version
        OR session_record.environment <> NEW.environment
        OR session_record.route_family <> NEW.route_family
        OR session_record.route_root_label <> NEW.route_root_label
        OR session_record.route_root_label_display <> NEW.route_root_label_display
        OR session_record.route_path_segment <> NEW.route_path_segment
        OR session_record.route_href <> NEW.route_href
        OR session_record.route_app_host IS DISTINCT FROM NEW.route_app_host
      )
    THEN
      RAISE EXCEPTION 'namespace ownership start reservation does not match its session';
    END IF;
    RETURN NEW;
  END IF;

  IF ROW(
    NEW.reservation_id, NEW.namespace_session_id, NEW.actor_id,
    NEW.creation_intent_id, NEW.ceremony_intent_id, NEW.requirement_kind,
    NEW.generation, NEW.requirement_hash, NEW.expected_revision,
    NEW.client_idempotency_key, NEW.request_hash, NEW.provider_id,
    NEW.provider_binding_hash, NEW.provider_configuration_kind,
    NEW.provider_configuration_ref, NEW.provider_configuration_version,
    NEW.protocol_version, NEW.environment, NEW.route_family,
    NEW.route_root_label, NEW.route_root_label_display, NEW.route_path_segment,
    NEW.route_href, NEW.route_app_host, NEW.created_at
  ) IS DISTINCT FROM ROW(
    OLD.reservation_id, OLD.namespace_session_id, OLD.actor_id,
    OLD.creation_intent_id, OLD.ceremony_intent_id, OLD.requirement_kind,
    OLD.generation, OLD.requirement_hash, OLD.expected_revision,
    OLD.client_idempotency_key, OLD.request_hash, OLD.provider_id,
    OLD.provider_binding_hash, OLD.provider_configuration_kind,
    OLD.provider_configuration_ref, OLD.provider_configuration_version,
    OLD.protocol_version, OLD.environment, OLD.route_family,
    OLD.route_root_label, OLD.route_root_label_display, OLD.route_path_segment,
    OLD.route_href, OLD.route_app_host, OLD.created_at
  ) THEN
    RAISE EXCEPTION 'namespace ownership start reservation authority is immutable';
  END IF;

  IF OLD.state = NEW.state
    AND OLD.fence_token = NEW.fence_token
    AND OLD.lease_expires_at = NEW.lease_expires_at
  THEN
    RETURN NEW;
  END IF;

  SELECT * INTO session_record
    FROM namespace_ownership_sessions
   WHERE namespace_session_id = NEW.namespace_session_id
     AND actor_id = NEW.actor_id
   FOR SHARE;
  IF session_record.namespace_session_id IS NOT NULL
    AND NEW.lease_expires_at > session_record.expires_at
  THEN
    RAISE EXCEPTION 'namespace ownership start lease exceeds its session expiry';
  END IF;

  IF OLD.state = 'acquired'
    AND NEW.state IN ('released', 'finalized')
    AND NEW.fence_token = OLD.fence_token
    AND NEW.lease_expires_at > clock_timestamp()
  THEN
    RETURN NEW;
  END IF;

  IF OLD.state = 'released'
    AND NEW.state = 'acquired'
    AND NEW.fence_token = OLD.fence_token + 1
    AND NEW.lease_expires_at > clock_timestamp()
  THEN
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'namespace ownership start reservation transition is not allowed: % -> %',
    OLD.state, NEW.state;
END;
$$;

CREATE FUNCTION guard_operator_managed_root_registry_current_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'operator-managed root registry current authority cannot be deleted';
  END IF;
  IF NEW.registry_kind <> OLD.registry_kind
    OR NEW.activated_at < OLD.activated_at THEN
    RAISE EXCEPTION 'operator-managed root registry current identity is invalid';
  END IF;
  IF EXISTS (
    SELECT 1
      FROM operator_managed_route_activations AS activation
     WHERE activation.status = 'active'
       AND NOT operator_managed_registry_has_active_root(
         NEW.registry_reference,
         NEW.registry_version,
         NEW.registry_digest,
         activation.canonical_root
       )
  ) THEN
    RAISE EXCEPTION 'current operator-managed registry cannot remove an active route';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_operator_managed_route_activation_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'operator-managed route activations are retained';
  END IF;
  IF ROW(
    NEW.operator_route_activation_id,
    NEW.community_id,
    NEW.route_binding_id,
    NEW.family,
    NEW.canonical_root,
    NEW.operator_principal_id,
    NEW.operator_authority_grant_id,
    NEW.operator_managed_root_registry_reference,
    NEW.operator_managed_root_registry_version,
    NEW.operator_managed_root_registry_digest,
    NEW.activated_at
  ) IS DISTINCT FROM ROW(
    OLD.operator_route_activation_id,
    OLD.community_id,
    OLD.route_binding_id,
    OLD.family,
    OLD.canonical_root,
    OLD.operator_principal_id,
    OLD.operator_authority_grant_id,
    OLD.operator_managed_root_registry_reference,
    OLD.operator_managed_root_registry_version,
    OLD.operator_managed_root_registry_digest,
    OLD.activated_at
  ) THEN
    RAISE EXCEPTION 'operator-managed route activation identity is immutable';
  END IF;
  IF OLD.status = 'revoked' THEN
    RAISE EXCEPTION 'revoked operator-managed route activation is terminal';
  END IF;
  IF NEW.status <> 'revoked'
    OR NEW.operator_route_activation_generation <> OLD.operator_route_activation_generation + 1 THEN
    RAISE EXCEPTION 'operator-managed route revocation must advance exactly once';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_persona_activity_presentation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'activity presentation selection cannot be deleted';
  END IF;
  IF TG_OP = 'UPDATE' AND (
    NEW.community_id IS DISTINCT FROM OLD.community_id
    OR NEW.account_id IS DISTINCT FROM OLD.account_id
    OR NEW.created_at IS DISTINCT FROM OLD.created_at
    OR NEW.updated_at < OLD.updated_at
  ) THEN
    RAISE EXCEPTION 'activity presentation identity is immutable';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_persona_activity_presentation_action() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'persona activity presentation actions are append-only';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_persona_wallet_assignment() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'persona wallet assignment cannot be deleted';
  END IF;
  IF NEW.assignment_id IS DISTINCT FROM OLD.assignment_id
     OR NEW.persona_id IS DISTINCT FROM OLD.persona_id
     OR NEW.account_id IS DISTINCT FROM OLD.account_id
     OR NEW.chain_account_kind IS DISTINCT FROM OLD.chain_account_kind
     OR NEW.hd_wallet_index IS DISTINCT FROM OLD.hd_wallet_index
     OR NEW.reservation_idempotency_key IS DISTINCT FROM OLD.reservation_idempotency_key
     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'persona wallet assignment identity is immutable';
  END IF;
  IF OLD.status = 'tombstoned' AND NEW IS DISTINCT FROM OLD THEN
    RAISE EXCEPTION 'tombstoned persona wallet assignment is immutable';
  END IF;
  IF OLD.status = 'active' AND NEW.status NOT IN ('active', 'tombstoned') THEN
    RAISE EXCEPTION 'active persona wallet assignment cannot be reopened';
  END IF;
  IF OLD.status = 'pending' AND NEW.status NOT IN ('pending', 'active', 'tombstoned') THEN
    RAISE EXCEPTION 'invalid persona wallet assignment transition';
  END IF;
  IF OLD.status <> 'pending'
     AND (NEW.privy_wallet_id IS DISTINCT FROM OLD.privy_wallet_id
       OR NEW.address IS DISTINCT FROM OLD.address
       OR NEW.assigned_at IS DISTINCT FROM OLD.assigned_at) THEN
    RAISE EXCEPTION 'assigned persona wallet authority is immutable';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_platform_operator_route_authority_grant_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF ROW(
    NEW.grant_id,
    NEW.operator_principal_id,
    NEW.authority,
    NEW.granted_at,
    NEW.granted_by_operator_principal_id
  ) IS DISTINCT FROM ROW(
    OLD.grant_id,
    OLD.operator_principal_id,
    OLD.authority,
    OLD.granted_at,
    OLD.granted_by_operator_principal_id
  ) THEN
    RAISE EXCEPTION 'platform operator route authority identity is immutable';
  END IF;
  IF OLD.status = 'revoked' THEN
    RAISE EXCEPTION 'revoked platform operator route authority is terminal';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_reward_asset_whitelist_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'reward asset whitelist rows cannot be deleted';
  END IF;
  IF ROW(
    NEW.chain_id, NEW.token_address, NEW.decimals, NEW.symbol, NEW.asset_kind,
    NEW.environment, NEW.policy_version, NEW.activated_at, NEW.created_at
  ) IS DISTINCT FROM ROW(
    OLD.chain_id, OLD.token_address, OLD.decimals, OLD.symbol, OLD.asset_kind,
    OLD.environment, OLD.policy_version, OLD.activated_at, OLD.created_at
  ) OR OLD.status <> 'active' OR NEW.status <> 'retired' THEN
    RAISE EXCEPTION 'reward asset whitelist only permits retirement';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_reward_availability_observation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'reward activity availability observations are append-only';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM posts post
     WHERE post.community_id = NEW.community_id AND post.post_id = NEW.post_id
       AND post.post_type = 'song'
  ) OR NOT EXISTS (
    SELECT 1 FROM media_publication_projections publication
     WHERE publication.community_id = NEW.community_id
       AND publication.post_id = NEW.post_id
       AND publication.audio_revision = NEW.audio_revision
  ) THEN
    RAISE EXCEPTION 'reward availability requires exact song publication';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_reward_chain_effect() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  previous_record reward_chain_effects%ROWTYPE;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'reward chain effects cannot be deleted';
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF NEW.state <> 'planned' THEN
      RAISE EXCEPTION 'reward chain effect must begin planned';
    END IF;
    IF NEW.replacement_of_effect_id IS NOT NULL THEN
      SELECT * INTO previous_record FROM reward_chain_effects
       WHERE effect_id = NEW.replacement_of_effect_id FOR UPDATE;
      IF previous_record.effect_id IS NULL OR previous_record.state <> 'replaced'
         OR previous_record.replaced_by_effect_id <> NEW.effect_id
         OR previous_record.effect_kind <> NEW.effect_kind
         OR previous_record.chain_id <> NEW.chain_id
         OR previous_record.signer_address <> NEW.signer_address
         OR previous_record.target_address <> NEW.target_address
         OR previous_record.value_wei <> NEW.value_wei
         OR previous_record.reserved_amount_atomic <> NEW.reserved_amount_atomic THEN
        RAISE EXCEPTION 'reward replacement effect identity is invalid';
      END IF;
    END IF;
    RETURN NEW;
  END IF;
  IF ROW(
    NEW.effect_id, NEW.effect_kind, NEW.chain_id, NEW.signer_address,
    NEW.target_address, NEW.value_wei, NEW.reserved_amount_atomic,
    NEW.replacement_of_effect_id, NEW.created_at
  ) IS DISTINCT FROM ROW(
    OLD.effect_id, OLD.effect_kind, OLD.chain_id, OLD.signer_address,
    OLD.target_address, OLD.value_wei, OLD.reserved_amount_atomic,
    OLD.replacement_of_effect_id, OLD.created_at
  ) THEN
    RAISE EXCEPTION 'reward chain effect identity is immutable';
  END IF;
  IF OLD.signed_transaction IS NOT NULL AND ROW(
    NEW.nonce, NEW.calldata, NEW.calldata_hash,
    NEW.signed_transaction, NEW.signed_transaction_hash
  ) IS DISTINCT FROM ROW(
    OLD.nonce, OLD.calldata, OLD.calldata_hash,
    OLD.signed_transaction, OLD.signed_transaction_hash
  ) THEN
    RAISE EXCEPTION 'prepared reward transaction bytes are immutable';
  END IF;
  IF NEW.version = OLD.version THEN
    IF ROW(
      NEW.state, NEW.settled_amount_atomic, NEW.nonce, NEW.calldata, NEW.calldata_hash,
      NEW.signed_transaction, NEW.signed_transaction_hash, NEW.transaction_hash,
      NEW.replaced_by_effect_id, NEW.receipt_status, NEW.receipt_block_number,
      NEW.receipt_block_hash, NEW.receipt_hash, NEW.confirmations,
      NEW.failure_class, NEW.failure_reason, NEW.prepared_at,
      NEW.broadcast_at, NEW.confirmed_at
    ) IS DISTINCT FROM ROW(
      OLD.state, OLD.settled_amount_atomic, OLD.nonce, OLD.calldata, OLD.calldata_hash,
      OLD.signed_transaction, OLD.signed_transaction_hash, OLD.transaction_hash,
      OLD.replaced_by_effect_id, OLD.receipt_status, OLD.receipt_block_number,
      OLD.receipt_block_hash, OLD.receipt_hash, OLD.confirmations,
      OLD.failure_class, OLD.failure_reason, OLD.prepared_at,
      OLD.broadcast_at, OLD.confirmed_at
    ) THEN
      RAISE EXCEPTION 'reward chain state change requires next version';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.version <> OLD.version + 1 OR NEW.updated_at <= OLD.updated_at THEN
    RAISE EXCEPTION 'reward chain transition requires next version and time';
  END IF;
  IF NOT (
    (OLD.state = 'planned' AND NEW.state IN ('nonce_reserved', 'reclaimable_failed', 'terminal_failed'))
    OR (OLD.state = 'nonce_reserved' AND NEW.state IN ('prepared', 'reclaimable_failed', 'terminal_failed'))
    OR (OLD.state = 'prepared' AND NEW.state IN (
      'broadcast_pending', 'reclaimable_failed', 'terminal_failed'
    ))
    OR (OLD.state = 'broadcast_pending' AND NEW.state IN (
      'confirming', 'confirmed', 'reverted', 'replaced', 'reconciliation_required'
    ))
    OR (OLD.state = 'confirming' AND NEW.state IN (
      'confirmed', 'reverted', 'replaced', 'reconciliation_required'
    ))
    OR (OLD.state = 'reconciliation_required' AND NEW.state IN (
      'confirming', 'confirmed', 'reverted', 'replaced', 'terminal_failed'
    ))
  ) THEN
    RAISE EXCEPTION 'invalid reward chain effect transition';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_reward_day_ledger() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'reward day ledgers are append-only';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_reward_erc20_transfer_receipt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  chain_record reward_chain_effects%ROWTYPE;
  attestation_record megapot_deployment_attestations%ROWTYPE;
  payout_record reward_payout_effects%ROWTYPE;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'reward ERC20 transfer receipt evidence is append-only';
  END IF;
  SELECT * INTO chain_record FROM reward_chain_effects
   WHERE effect_id = NEW.effect_id FOR SHARE;
  SELECT * INTO attestation_record FROM megapot_deployment_attestations
   WHERE attestation_id = NEW.attestation_id FOR SHARE;
  IF chain_record.state <> 'confirmed'
     OR chain_record.effect_kind <> NEW.transfer_purpose
     OR chain_record.signer_address <> NEW.sender_address
     OR chain_record.target_address <> NEW.token_address
     OR chain_record.settled_amount_atomic <> NEW.amount_atomic
     OR chain_record.transaction_hash <> NEW.transaction_hash
     OR chain_record.receipt_block_number <> NEW.block_number
     OR chain_record.receipt_block_hash <> NEW.block_hash
     OR chain_record.receipt_hash <> NEW.receipt_hash
     OR chain_record.confirmations <> NEW.confirmations
     OR attestation_record.chain_id <> chain_record.chain_id
     OR attestation_record.usdc_address <> NEW.token_address
     OR attestation_record.custody_address <> NEW.sender_address THEN
    RAISE EXCEPTION 'reward ERC20 transfer receipt does not match confirmed effect';
  END IF;
  IF NEW.transfer_purpose = 'reward_payout' THEN
    SELECT * INTO payout_record FROM reward_payout_effects
     WHERE payout_effect_id = NEW.effect_id;
    IF payout_record.attestation_id <> NEW.attestation_id
       OR payout_record.destination_address <> NEW.recipient_address
       OR payout_record.amount_atomic <> NEW.amount_atomic THEN
      RAISE EXCEPTION 'reward payout receipt does not match payout reservation';
    END IF;
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_reward_ledger_credit() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'reward ledger credits cannot be deleted';
  END IF;
  IF TG_OP = 'UPDATE' THEN
    IF ROW(
      NEW.credit_id, NEW.account_id, NEW.payout_persona_id, NEW.chain_id,
      NEW.token_address, NEW.amount_atomic, NEW.source_kind,
      NEW.source_reference, NEW.created_at
    ) IS DISTINCT FROM ROW(
      OLD.credit_id, OLD.account_id, OLD.payout_persona_id, OLD.chain_id,
      OLD.token_address, OLD.amount_atomic, OLD.source_kind,
      OLD.source_reference, OLD.created_at
    ) OR NEW.reserved_atomic < 0 OR NEW.paid_atomic < OLD.paid_atomic
       OR NEW.updated_at <= OLD.updated_at
       OR NOT (
         (OLD.state = 'credited' AND NEW.state = 'payout_reserved'
           AND OLD.reserved_atomic = 0
           AND NEW.reserved_atomic = OLD.amount_atomic - OLD.paid_atomic
           AND NEW.paid_atomic = OLD.paid_atomic)
         OR (OLD.state = 'payout_reserved' AND NEW.state = 'credited'
           AND NEW.reserved_atomic = 0 AND NEW.paid_atomic = OLD.paid_atomic)
         OR (OLD.state = 'payout_reserved'
           AND NEW.state IN ('payout_pending', 'reconciliation_required')
           AND NEW.reserved_atomic = OLD.reserved_atomic
           AND NEW.paid_atomic = OLD.paid_atomic)
         OR (OLD.state = 'payout_pending' AND NEW.state = 'reconciliation_required'
           AND NEW.reserved_atomic = OLD.reserved_atomic
           AND NEW.paid_atomic = OLD.paid_atomic)
         OR (OLD.state IN ('payout_pending', 'reconciliation_required')
           AND NEW.state = 'sent' AND NEW.reserved_atomic = 0
           AND NEW.paid_atomic = OLD.amount_atomic)
         OR (OLD.state = 'reconciliation_required'
           AND NEW.state IN ('credited', 'payout_reserved', 'payout_pending')
           AND NEW.paid_atomic = OLD.paid_atomic
           AND ((NEW.state = 'credited' AND NEW.reserved_atomic = 0)
             OR (NEW.state <> 'credited'
               AND NEW.reserved_atomic = OLD.reserved_atomic)))
       ) THEN
      RAISE EXCEPTION 'invalid reward ledger credit transition';
    END IF;
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_reward_payout_effect() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  chain_record reward_chain_effects%ROWTYPE;
  credit_record reward_ledger_credits%ROWTYPE;
  wallet_record persona_wallet_assignments%ROWTYPE;
  solvency_record custody_solvency_observations%ROWTYPE;
  attestation_record megapot_deployment_attestations%ROWTYPE;
  live_reserved_purchase NUMERIC(78, 0);
  live_outstanding_credit NUMERIC(78, 0);
  live_pending_refund NUMERIC(78, 0);
  live_shared_sponsorship NUMERIC(78, 0);
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'reward payout effects are append-only';
  END IF;
  SELECT * INTO chain_record FROM reward_chain_effects
   WHERE effect_id = NEW.payout_effect_id FOR SHARE;
  SELECT * INTO credit_record FROM reward_ledger_credits
   WHERE credit_id = NEW.credit_id FOR SHARE;
  SELECT * INTO wallet_record FROM persona_wallet_assignments
   WHERE assignment_id = NEW.wallet_assignment_id FOR SHARE;
  SELECT * INTO solvency_record FROM custody_solvency_observations
   WHERE observation_id = NEW.solvency_observation_id FOR SHARE;
  SELECT * INTO attestation_record FROM megapot_deployment_attestations
   WHERE attestation_id = NEW.attestation_id FOR SHARE;
  SELECT COALESCE(sum(reserved_atomic), 0) INTO live_reserved_purchase
    FROM song_reward_offer_legs WHERE kind='megapot_pool' AND funding_source='leg_budget'
      AND chain_id=credit_record.chain_id AND token_address=credit_record.token_address;
  SELECT COALESCE(sum(amount_atomic - paid_atomic), 0) INTO live_outstanding_credit
    FROM reward_ledger_credits WHERE state <> 'sent'
      AND chain_id=credit_record.chain_id AND token_address=credit_record.token_address;
  SELECT COALESCE(sum(funded_atomic - reserved_atomic - spent_atomic
      - fulfilled_atomic - refunded_atomic), 0) INTO live_pending_refund
    FROM song_reward_offer_legs WHERE funding_source='leg_budget'
      AND chain_id=credit_record.chain_id AND token_address=credit_record.token_address;
  SELECT COALESCE(sum(funded_atomic + winnings_credited_atomic
      - spent_atomic - withdrawn_atomic), 0) INTO live_shared_sponsorship
    FROM platform_sponsorship_budgets
    WHERE chain_id=credit_record.chain_id AND token_address=credit_record.token_address;
  IF chain_record.effect_kind <> 'reward_payout'
     OR chain_record.reserved_amount_atomic <> NEW.amount_atomic
     OR chain_record.chain_id <> credit_record.chain_id
     OR chain_record.signer_address <> attestation_record.custody_address
     OR chain_record.target_address <> credit_record.token_address
     OR attestation_record.status <> 'active'
     OR attestation_record.chain_id <> credit_record.chain_id
     OR attestation_record.usdc_address <> credit_record.token_address
     OR credit_record.account_id <> NEW.account_id
     OR credit_record.payout_persona_id <> NEW.payout_persona_id
     OR credit_record.amount_atomic - credit_record.paid_atomic < NEW.amount_atomic
     OR credit_record.state <> 'payout_reserved'
     OR credit_record.reserved_atomic <> NEW.amount_atomic
     OR wallet_record.account_id <> NEW.account_id
     OR wallet_record.persona_id <> NEW.payout_persona_id
     OR wallet_record.status <> 'active'
     OR wallet_record.address <> NEW.destination_address
     OR solvency_record.attestation_id <> NEW.attestation_id
     OR solvency_record.chain_id <> credit_record.chain_id
     OR solvency_record.custody_address <> chain_record.signer_address
     OR solvency_record.token_address <> credit_record.token_address
     OR solvency_record.expires_at <= clock_timestamp()
     OR NOT solvency_record.solvent
     OR solvency_record.balance_atomic <> NEW.custody_balance_before_atomic
     OR solvency_record.balance_atomic < live_reserved_purchase
       + live_outstanding_credit + live_pending_refund + live_shared_sponsorship THEN
    RAISE EXCEPTION 'reward payout does not match credit and active persona wallet';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_reward_refund_effect() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  chain_record reward_chain_effects%ROWTYPE;
  funding_record song_reward_leg_funding_effects%ROWTYPE;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'reward refund effects are append-only';
  END IF;
  SELECT * INTO chain_record FROM reward_chain_effects
   WHERE effect_id = NEW.refund_effect_id FOR SHARE;
  SELECT * INTO funding_record FROM song_reward_leg_funding_effects
   WHERE funding_effect_id = NEW.funding_effect_id FOR SHARE;
  IF chain_record.effect_kind <> 'reward_refund'
     OR chain_record.reserved_amount_atomic <> NEW.amount_atomic
     OR chain_record.target_address <> NEW.destination_address
     OR funding_record.leg_id <> NEW.leg_id
     OR funding_record.funder_account_id <> NEW.funder_account_id
     OR funding_record.state <> 'confirmed'
     OR NEW.amount_atomic > funding_record.confirmed_amount_atomic THEN
    RAISE EXCEPTION 'reward refund does not match confirmed contribution';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_reward_signer_nonce() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'reward signer nonce fences cannot be deleted';
  END IF;
  IF TG_OP = 'UPDATE' AND (
    NEW.chain_id <> OLD.chain_id OR NEW.signer_address <> OLD.signer_address
    OR NEW.next_nonce < OLD.next_nonce OR NEW.fence_version <> OLD.fence_version + 1
    OR NEW.observed_block_number < OLD.observed_block_number
    OR NEW.observed_at < OLD.observed_at OR NEW.updated_at <= OLD.updated_at
  ) THEN
    RAISE EXCEPTION 'invalid reward signer nonce fence update';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_song_reward_funding_effect() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  leg_record song_reward_offer_legs%ROWTYPE;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'song reward funding effects cannot be deleted';
  END IF;
  SELECT * INTO leg_record FROM song_reward_offer_legs
   WHERE leg_id = NEW.leg_id FOR SHARE;
  IF leg_record.leg_id IS NULL OR NEW.chain_id <> leg_record.chain_id
     OR NEW.token_address <> leg_record.token_address THEN
    RAISE EXCEPTION 'song reward funding asset does not match leg';
  END IF;
  IF leg_record.kind = 'megapot_pool'
     AND leg_record.empty_pool_policy = 'funder_fallback'
     AND NEW.funder_account_id <> leg_record.funder_account_id THEN
    RAISE EXCEPTION 'fallback_sponsor_mismatch';
  END IF;
  IF TG_OP = 'UPDATE' THEN
    IF ROW(
      NEW.funding_effect_id, NEW.leg_id, NEW.funder_account_id, NEW.chain_id,
      NEW.token_address, NEW.sender_address, NEW.recipient_address,
      NEW.expected_amount_atomic, NEW.required_confirmations, NEW.created_at
    ) IS DISTINCT FROM ROW(
      OLD.funding_effect_id, OLD.leg_id, OLD.funder_account_id, OLD.chain_id,
      OLD.token_address, OLD.sender_address, OLD.recipient_address,
      OLD.expected_amount_atomic, OLD.required_confirmations, OLD.created_at
    ) THEN
      RAISE EXCEPTION 'song reward funding identity is immutable';
    END IF;
    IF NOT (
      NEW.state = OLD.state
      OR (OLD.state = 'planned' AND NEW.state IN (
        'confirming', 'reclaimable_failed', 'reconciliation_required'
      ))
      OR (OLD.state = 'confirming' AND NEW.state IN (
        'confirmed', 'reverted', 'reclaimable_failed', 'reconciliation_required'
      ))
      OR (OLD.state = 'reconciliation_required' AND NEW.state IN (
        'confirming', 'confirmed', 'reverted'
      ))
    ) THEN
      RAISE EXCEPTION 'invalid song reward funding transition';
    END IF;
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_song_reward_offer() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  post_record posts%ROWTYPE;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'song reward offers cannot be deleted';
  END IF;
  SELECT * INTO post_record FROM posts
   WHERE community_id = NEW.community_id AND post_id = NEW.post_id FOR SHARE;
  IF post_record.post_id IS NULL OR post_record.post_type <> 'song'
     OR NOT EXISTS (
       SELECT 1 FROM media_publication_projections publication
        WHERE publication.community_id = NEW.community_id
          AND publication.post_id = NEW.post_id
          AND publication.audio_revision = NEW.audio_revision
     ) THEN
    RAISE EXCEPTION 'song reward offer requires exact published song revision';
  END IF;
  IF TG_OP = 'INSERT' AND NEW.status <> 'draft' THEN
    RAISE EXCEPTION 'song reward offer must begin as draft';
  END IF;
  IF TG_OP = 'UPDATE' THEN
    IF ROW(
      NEW.offer_id, NEW.community_id, NEW.post_id, NEW.audio_revision,
      NEW.created_by_account_id, NEW.starts_at, NEW.ends_at,
      NEW.owner_policy_snapshot, NEW.terms_hash, NEW.created_at
    ) IS DISTINCT FROM ROW(
      OLD.offer_id, OLD.community_id, OLD.post_id, OLD.audio_revision,
      OLD.created_by_account_id, OLD.starts_at, OLD.ends_at,
      OLD.owner_policy_snapshot, OLD.terms_hash, OLD.created_at
    ) THEN
      RAISE EXCEPTION 'song reward offer terms are immutable';
    END IF;
    IF OLD.status IN ('exhausted', 'expired', 'ended') AND NEW IS DISTINCT FROM OLD THEN
      RAISE EXCEPTION 'terminal song reward offer is immutable';
    END IF;
    IF NOT (
      NEW.status = OLD.status
      OR (OLD.status = 'draft' AND NEW.status IN ('active', 'ended'))
      OR (OLD.status = 'active' AND NEW.status IN (
        'paused', 'exhausted', 'expired', 'ended', 'operational_hold'
      ))
      OR (OLD.status = 'paused' AND NEW.status IN ('active', 'expired', 'ended', 'operational_hold'))
      OR (OLD.status = 'operational_hold' AND NEW.status IN ('active', 'ended'))
    ) THEN
      RAISE EXCEPTION 'invalid song reward offer transition';
    END IF;
    IF NEW.status <> OLD.status AND NEW.updated_at <= OLD.updated_at THEN
      RAISE EXCEPTION 'song reward offer transition time must advance';
    END IF;
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_song_reward_offer_action() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'song reward offer actions are append-only';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM song_reward_offers offer
     WHERE offer.offer_id = NEW.offer_id
       AND offer.created_by_account_id = CASE
         WHEN NEW.endpoint_template = '/communities/:communityId/posts/:postId/reward-offers'
         THEN NEW.account_id
         ELSE offer.created_by_account_id
       END
  ) OR (NEW.leg_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM song_reward_offer_legs leg
     WHERE leg.leg_id = NEW.leg_id AND leg.offer_id = NEW.offer_id
  )) OR (NEW.funding_effect_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM song_reward_leg_funding_effects funding
     WHERE funding.funding_effect_id = NEW.funding_effect_id
       AND funding.leg_id = NEW.leg_id
       AND funding.funder_account_id = NEW.account_id
  )) THEN
    RAISE EXCEPTION 'song reward offer action result is not exact';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_song_reward_offer_leg() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  offer_record song_reward_offers%ROWTYPE;
  attestation_record megapot_deployment_attestations%ROWTYPE;
  activity TEXT;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'song reward offer legs cannot be deleted';
  END IF;
  SELECT * INTO offer_record FROM song_reward_offers
   WHERE offer_id = NEW.offer_id FOR SHARE;
  IF offer_record.offer_id IS NULL THEN
    RAISE EXCEPTION 'song reward offer leg requires offer';
  END IF;
  IF TG_OP = 'INSERT' AND NEW.status <> 'draft' THEN
    RAISE EXCEPTION 'song reward offer leg must begin as draft';
  END IF;
  IF NEW.kind = 'megapot_pool' THEN
    SELECT * INTO attestation_record FROM megapot_deployment_attestations
     WHERE attestation_id = NEW.attestation_id FOR SHARE;
    IF attestation_record.attestation_id IS NULL
       OR attestation_record.chain_id <> NEW.chain_id
       OR attestation_record.usdc_address <> NEW.token_address
       OR attestation_record.status <> 'active' THEN
      RAISE EXCEPTION 'Megapot pool leg requires active exact deployment attestation';
    END IF;
    FOREACH activity IN ARRAY NEW.eligible_activities
    LOOP
      IF NOT EXISTS (
        SELECT 1 FROM activity_registry registry
         WHERE registry.activity_key = activity AND registry.status = 'active'
      ) THEN
        RAISE EXCEPTION 'Megapot pool leg activity is not active';
      END IF;
    END LOOP;
    IF NEW.status = 'active' THEN
      IF offer_record.status <> 'active' THEN
        RAISE EXCEPTION 'Megapot pool leg requires active offer';
      END IF;
      IF attestation_record.environment = 'production'
         AND NEW.legal_activation_gate <> 'production_approved' THEN
        RAISE EXCEPTION 'production Megapot pool activation is not legally approved';
      END IF;
      IF NEW.empty_pool_policy = 'funder_fallback'
         AND NEW.funding_source = 'leg_budget' THEN
        IF NOT EXISTS (
          SELECT 1 FROM posts post
           WHERE post.community_id = offer_record.community_id
             AND post.post_id = offer_record.post_id
             AND post.post_type = 'song' AND post.status = 'published'
             AND post.visibility = 'public'
        ) THEN
          RAISE EXCEPTION 'external fallback requires discoverable song';
        END IF;
        FOREACH activity IN ARRAY NEW.eligible_activities
        LOOP
          IF NOT EXISTS (
            SELECT 1 FROM reward_activity_availability_observations availability
             WHERE availability.community_id = offer_record.community_id
               AND availability.post_id = offer_record.post_id
               AND availability.audio_revision = offer_record.audio_revision
               AND availability.activity_key = activity
               AND availability.state = 'available'
               AND availability.expires_at > clock_timestamp()
          ) THEN
            RAISE EXCEPTION 'external fallback activity is unavailable';
          END IF;
        END LOOP;
      END IF;
    END IF;
  END IF;
  IF TG_OP = 'UPDATE' THEN
    IF ROW(
      NEW.leg_id, NEW.offer_id, NEW.kind, NEW.funder_account_id, NEW.refund_policy,
      NEW.leg_terms_hash, NEW.participation_starts_at, NEW.chain_id, NEW.token_address,
      NEW.token_decimals, NEW.amount_per_claim_atomic, NEW.max_claims,
      NEW.tickets_per_drawing, NEW.max_ticket_price_atomic, NEW.entry_cutoff_seconds,
      NEW.beneficiary_algorithm_version, NEW.ticket_selection_version, NEW.attestation_id,
      NEW.participation_starts_drawing_id, NEW.eligible_activities, NEW.min_score_bps,
      NEW.empty_pool_policy, NEW.funding_source, NEW.fallback_beneficiary_account_id,
      NEW.fallback_payout_persona_id, NEW.referral_allocation_version,
      NEW.referral_policy_hash, NEW.referral_disclosed_at, NEW.legal_activation_gate,
      NEW.created_at
    ) IS DISTINCT FROM ROW(
      OLD.leg_id, OLD.offer_id, OLD.kind, OLD.funder_account_id, OLD.refund_policy,
      OLD.leg_terms_hash, OLD.participation_starts_at, OLD.chain_id, OLD.token_address,
      OLD.token_decimals, OLD.amount_per_claim_atomic, OLD.max_claims,
      OLD.tickets_per_drawing, OLD.max_ticket_price_atomic, OLD.entry_cutoff_seconds,
      OLD.beneficiary_algorithm_version, OLD.ticket_selection_version, OLD.attestation_id,
      OLD.participation_starts_drawing_id, OLD.eligible_activities, OLD.min_score_bps,
      OLD.empty_pool_policy, OLD.funding_source, OLD.fallback_beneficiary_account_id,
      OLD.fallback_payout_persona_id, OLD.referral_allocation_version,
      OLD.referral_policy_hash, OLD.referral_disclosed_at, OLD.legal_activation_gate,
      OLD.created_at
    ) THEN
      RAISE EXCEPTION 'song reward offer leg terms are immutable';
    END IF;
    IF NEW.funded_atomic < OLD.funded_atomic OR NEW.reserved_atomic < 0
       OR NEW.spent_atomic < OLD.spent_atomic OR NEW.fulfilled_atomic < OLD.fulfilled_atomic
       OR NEW.refunded_atomic < OLD.refunded_atomic THEN
      RAISE EXCEPTION 'song reward offer leg accounting cannot reverse';
    END IF;
    IF OLD.status IN ('exhausted', 'ended') AND NEW IS DISTINCT FROM OLD THEN
      RAISE EXCEPTION 'terminal song reward offer leg is immutable';
    END IF;
    IF NOT (
      NEW.status = OLD.status
      OR (OLD.status = 'draft' AND NEW.status IN ('funding', 'active', 'ended'))
      OR (OLD.status = 'funding' AND NEW.status IN ('active', 'ended', 'operational_hold'))
      OR (OLD.status = 'active' AND NEW.status IN (
        'paused', 'exhausted', 'ended', 'operational_hold'
      ))
      OR (OLD.status = 'paused' AND NEW.status IN ('active', 'ended', 'operational_hold'))
      OR (OLD.status = 'operational_hold' AND NEW.status IN ('active', 'ended'))
    ) THEN
      RAISE EXCEPTION 'invalid song reward offer leg transition';
    END IF;
    IF NEW.updated_at < OLD.updated_at THEN
      RAISE EXCEPTION 'song reward offer leg update time cannot reverse';
    END IF;
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_song_streak_day_activity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'song streak day activity rows cannot be deleted';
  END IF;
  IF TG_OP = 'UPDATE' AND (
    ROW(NEW.account_id, NEW.community_id, NEW.post_id, NEW.streak_day,
      NEW.activity_key, NEW.first_qualified_at)
    IS DISTINCT FROM
    ROW(OLD.account_id, OLD.community_id, OLD.post_id, OLD.streak_day,
      OLD.activity_key, OLD.first_qualified_at)
    OR NEW.qualification_count <> OLD.qualification_count + 1
    OR NEW.last_qualified_at < OLD.last_qualified_at
    OR NEW.last_qualification_id IS NOT DISTINCT FROM OLD.last_qualification_id
  ) THEN
    RAISE EXCEPTION 'song streak day activity updates must append one qualification';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_sponsor_daily_totals() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'sponsor daily totals cannot be deleted';
  END IF;
  IF TG_OP = 'UPDATE' AND (
    ROW(NEW.sponsor_account_id, NEW.sponsor_day, NEW.sponsor_kind,
      NEW.ticket_ceiling, NEW.spend_ceiling_atomic, NEW.created_at)
    IS DISTINCT FROM
    ROW(OLD.sponsor_account_id, OLD.sponsor_day, OLD.sponsor_kind,
      OLD.ticket_ceiling, OLD.spend_ceiling_atomic, OLD.created_at)
    OR NEW.reserved_ticket_count < OLD.reserved_ticket_count
    OR NEW.confirmed_ticket_count < OLD.confirmed_ticket_count
    OR NEW.released_ticket_count < OLD.released_ticket_count
    OR NEW.reserved_spend_atomic < OLD.reserved_spend_atomic
    OR NEW.confirmed_spend_atomic < OLD.confirmed_spend_atomic
    OR NEW.released_spend_atomic < OLD.released_spend_atomic
    OR NEW.updated_at <= OLD.updated_at
  ) THEN
    RAISE EXCEPTION 'invalid sponsor daily total update';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_streak_projection() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'streak projections cannot be deleted';
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.recomputed_at < OLD.recomputed_at THEN
    RAISE EXCEPTION 'streak projection recompute time cannot move backward';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_study_session() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  item_count INTEGER;
  answered_count INTEGER;
  correct_count INTEGER;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Study sessions cannot be deleted';
  END IF;
  IF NOT active_owned_persona(NEW.account_id, NEW.persona_id)
     OR NOT active_community_effect(NEW.community_id, NEW.account_id)
     OR NOT EXISTS (SELECT 1 FROM pg_timezone_names WHERE name = NEW.timezone)
     OR NOT EXISTS (
       SELECT 1 FROM account_streak_clocks
        WHERE account_id = NEW.account_id AND timezone = NEW.timezone
     ) THEN
    RAISE EXCEPTION 'Study session account, persona, community, or timezone is ineligible';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM posts
     WHERE community_id = NEW.community_id AND post_id = NEW.post_id
       AND post_type = 'song' AND status = 'published' AND visibility = 'public'
  ) THEN
    RAISE EXCEPTION 'Study sessions require a public published song';
  END IF;
  IF TG_OP = 'UPDATE' THEN
    IF ROW(
      NEW.session_id, NEW.account_id, NEW.persona_id, NEW.community_id, NEW.post_id,
      NEW.audio_revision, NEW.lyrics_revision, NEW.source_revision,
      NEW.source_producer_id, NEW.source_producer_revision, NEW.source_snapshot_hash,
      NEW.qualification_policy_version_id, NEW.endpoint_template,
      NEW.idempotency_key, NEW.request_hash, NEW.timezone,
      NEW.qualifying_exercise_count, NEW.required_correct, NEW.created_at
    ) IS DISTINCT FROM ROW(
      OLD.session_id, OLD.account_id, OLD.persona_id, OLD.community_id, OLD.post_id,
      OLD.audio_revision, OLD.lyrics_revision, OLD.source_revision,
      OLD.source_producer_id, OLD.source_producer_revision, OLD.source_snapshot_hash,
      OLD.qualification_policy_version_id, OLD.endpoint_template,
      OLD.idempotency_key, OLD.request_hash, OLD.timezone,
      OLD.qualifying_exercise_count, OLD.required_correct, OLD.created_at
    ) THEN
      RAISE EXCEPTION 'Study session authority is immutable';
    END IF;
    IF OLD.status = 'completed' AND NEW IS DISTINCT FROM OLD THEN
      RAISE EXCEPTION 'completed Study sessions are immutable';
    END IF;
    IF OLD.status = 'active' AND NEW.status = 'completed' THEN
      SELECT count(*),
             count(*) FILTER (WHERE answer_count > 0),
             count(*) FILTER (WHERE first_pass_outcome = 'correct')
        INTO item_count, answered_count, correct_count
        FROM study_session_items WHERE session_id = NEW.session_id;
      IF item_count <> NEW.qualifying_exercise_count
         OR answered_count <> NEW.answered_exercise_count
         OR correct_count <> NEW.first_pass_correct
         OR NEW.streak_day <> (NEW.completed_at AT TIME ZONE NEW.timezone)::date THEN
        RAISE EXCEPTION 'Study completion is not derived from frozen item evidence';
      END IF;
    ELSIF NEW IS DISTINCT FROM OLD THEN
      RAISE EXCEPTION 'invalid Study session transition';
    END IF;
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_study_session_answer() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  item_record study_session_items%ROWTYPE;
  session_record study_sessions%ROWTYPE;
  expected_outcome TEXT;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'Study answers are append-only';
  END IF;
  SELECT * INTO session_record FROM study_sessions WHERE session_id = NEW.session_id FOR SHARE;
  SELECT * INTO item_record FROM study_session_items
   WHERE session_id = NEW.session_id AND session_item_id = NEW.session_item_id FOR SHARE;
  IF session_record.status <> 'active' OR item_record.session_item_id IS NULL THEN
    RAISE EXCEPTION 'Study answers require an active bound item';
  END IF;
  IF NEW.attempt_number <> item_record.answer_count + 1
     OR NEW.first_pass IS DISTINCT FROM (NEW.attempt_number = 1)
     OR NOT valid_study_answer_v1(NEW.answer, item_record.prompt->>'kind') THEN
    RAISE EXCEPTION 'Study answer sequence or shape is invalid';
  END IF;
  expected_outcome := CASE
    WHEN grade_study_answer_v1(NEW.answer, item_record.answer_key) THEN 'correct'
    ELSE 'incorrect'
  END;
  IF NEW.outcome <> expected_outcome THEN
    RAISE EXCEPTION 'Study answer outcome is not server-derived';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_study_session_item() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  session_record study_sessions%ROWTYPE;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Study session items cannot be deleted';
  END IF;
  SELECT * INTO session_record FROM study_sessions WHERE session_id = NEW.session_id FOR SHARE;
  IF session_record.session_id IS NULL OR session_record.status <> 'active' THEN
    RAISE EXCEPTION 'Study items require an active session';
  END IF;
  IF NOT valid_study_item_v1(NEW.prompt, NEW.answer_key) THEN
    RAISE EXCEPTION 'Study item prompt and answer key are invalid';
  END IF;
  IF TG_OP = 'UPDATE' AND (
    NEW.session_id IS DISTINCT FROM OLD.session_id
    OR NEW.session_item_id IS DISTINCT FROM OLD.session_item_id
    OR NEW.ordinal IS DISTINCT FROM OLD.ordinal
    OR NEW.source_item_key IS DISTINCT FROM OLD.source_item_key
    OR NEW.prompt IS DISTINCT FROM OLD.prompt
    OR NEW.answer_key IS DISTINCT FROM OLD.answer_key
    OR NEW.presentation_count IS DISTINCT FROM OLD.presentation_count
    OR NEW.created_at IS DISTINCT FROM OLD.created_at
    OR NEW.answer_count < OLD.answer_count
    OR (OLD.first_pass_outcome IS NOT NULL
      AND NEW.first_pass_outcome IS DISTINCT FROM OLD.first_pass_outcome)
  ) THEN
    RAISE EXCEPTION 'Study session item evidence is immutable';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_text_content_submission_response_snapshot() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.response_snapshot_bytes IS DISTINCT FROM OLD.response_snapshot_bytes
    OR NEW.response_snapshot_sha256 IS DISTINCT FROM OLD.response_snapshot_sha256
  THEN
    RAISE EXCEPTION 'text content submission response snapshot is immutable';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_text_content_submission_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF ROW(
    NEW.community_id, NEW.submission_id, NEW.operation_id, NEW.actor_user_id,
    NEW.surface, NEW.idempotency_key, NEW.request_hash, NEW.moderation_decision,
    NEW.policy_revision_id, NEW.policy_hash, NEW.input_sha256,
    NEW.internal_reason_codes, NEW.evidence_ref, NEW.created_at,
    NEW.response_snapshot_bytes, NEW.response_snapshot_sha256
  ) IS DISTINCT FROM ROW(
    OLD.community_id, OLD.submission_id, OLD.operation_id, OLD.actor_user_id,
    OLD.surface, OLD.idempotency_key, OLD.request_hash, OLD.moderation_decision,
    OLD.policy_revision_id, OLD.policy_hash, OLD.input_sha256,
    OLD.internal_reason_codes, OLD.evidence_ref, OLD.created_at,
    OLD.response_snapshot_bytes, OLD.response_snapshot_sha256
  ) THEN
    RAISE EXCEPTION 'text content submission evidence and creation snapshot are immutable';
  END IF;
  IF OLD.status <> 'manual_review' OR NEW.status NOT IN ('published', 'blocked') THEN
    RAISE EXCEPTION 'text content submission transition is not allowed: % -> %', OLD.status, NEW.status;
  END IF;
  IF NEW.updated_at <= OLD.updated_at THEN
    RAISE EXCEPTION 'text content submission updated_at must advance';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_text_moderation_case_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF ROW(NEW.community_id, NEW.case_id, NEW.submission_id, NEW.created_at)
    IS DISTINCT FROM ROW(OLD.community_id, OLD.case_id, OLD.submission_id, OLD.created_at)
  THEN
    RAISE EXCEPTION 'text moderation case identity is immutable';
  END IF;
  IF OLD.status <> 'open' OR NEW.status NOT IN ('approved', 'dismissed', 'blocked') THEN
    RAISE EXCEPTION 'text moderation case transition is not allowed: % -> %',
      OLD.status,
      NEW.status;
  END IF;
  IF NEW.updated_at <= OLD.updated_at THEN
    RAISE EXCEPTION 'text moderation case updated_at must advance';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION has_community_route_authority(expected_community_id text, expected_principal_user_id text) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  SELECT EXISTS (
    SELECT 1
      FROM community_route_authority_grants AS authority_grant
     WHERE authority_grant.community_id = expected_community_id
       AND authority_grant.principal_user_id = expected_principal_user_id
       AND authority_grant.authority = 'manage_routes'
       AND authority_grant.status = 'active'
  )
$$;

CREATE FUNCTION identity_credentials_enforce_lifecycle() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'identity credentials cannot be deleted'
      USING ERRCODE = '23514', CONSTRAINT = 'identity_credentials_delete_forbidden';
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.status <> 'active' OR NEW.tombstoned_at IS NOT NULL THEN
      RAISE EXCEPTION 'identity credentials must be inserted active'
        USING ERRCODE = '23514', CONSTRAINT = 'identity_credentials_insert_active';
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.credential_id IS DISTINCT FROM OLD.credential_id
    OR NEW.provider IS DISTINCT FROM OLD.provider
    OR NEW.provider_app_id IS DISTINCT FROM OLD.provider_app_id
    OR NEW.provider_subject IS DISTINCT FROM OLD.provider_subject
    OR NEW.canonical_user_id IS DISTINCT FROM OLD.canonical_user_id
    OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'identity credential ownership and identity are immutable'
      USING ERRCODE = '23514', CONSTRAINT = 'identity_credentials_identity_immutable';
  END IF;

  IF OLD.status = 'tombstoned' THEN
    RAISE EXCEPTION 'identity credential tombstones are immutable'
      USING ERRCODE = '23514', CONSTRAINT = 'identity_credentials_tombstone_terminal';
  END IF;

  IF NEW.status = 'tombstoned' THEN
    NEW.tombstoned_at := now();
  ELSIF NEW.status <> 'active' OR NEW.tombstoned_at IS NOT NULL THEN
    RAISE EXCEPTION 'invalid identity credential lifecycle transition'
      USING ERRCODE = '23514', CONSTRAINT = 'identity_credentials_lifecycle';
  END IF;

  NEW.updated_at := now();
  RETURN NEW;
END;
$$;

CREATE FUNCTION is_community_route_root_label(route_family text, root_label text) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT
    AS $_$
  SELECT CASE route_family
    WHEN 'hns' THEN
      octet_length(root_label) BETWEEN 1 AND 63
      AND root_label ~ '^[a-z0-9](?:[a-z0-9_-]{0,61}[a-z0-9])?$'
      AND root_label NOT IN ('example', 'invalid', 'local', 'localhost', 'test')
    WHEN 'spaces' THEN
      octet_length(root_label) BETWEEN 1 AND 62
      AND root_label ~ '^[a-z0-9-]+$'
      AND CASE
        WHEN left(root_label, 4) = 'xn--' AND octet_length(root_label) > 4
          THEN substring(root_label FROM 5)
        ELSE root_label
      END ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'
    ELSE FALSE
  END;
$_$;

CREATE FUNCTION is_community_route_root_label_display(root_label_display text) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT
    AS $$
  SELECT octet_length(root_label_display) BETWEEN 1 AND 255
    AND root_label_display = btrim(root_label_display)
    AND root_label_display !~ '[[:cntrl:]]'
    AND position('@' IN root_label_display) = 0
    AND position('.' IN root_label_display) = 0
    AND position('%' IN root_label_display) = 0
    AND position('/' IN root_label_display) = 0
    AND position(E'\\' IN root_label_display) = 0;
$$;

CREATE FUNCTION is_hns_host_persistence_identity(input_value text, maximum_bytes integer) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT input_value IS NOT NULL
    AND btrim(input_value) <> ''
    AND input_value = btrim(input_value)
    AND octet_length(input_value) <= maximum_bytes
    AND input_value !~ '[[:cntrl:]]'
$$;

CREATE FUNCTION is_operator_managed_root_registry_document(exact_bytes bytea, expected_reference text, expected_version bigint) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
DECLARE
  document JSONB;
  entries JSONB;
  canonical_entries TEXT;
  canonical_document TEXT;
  invalid_entries BIGINT;
  reordered_entries BIGINT;
BEGIN
  IF exact_bytes IS NULL
    OR octet_length(exact_bytes) = 0
    OR octet_length(exact_bytes) > 65536
    OR btrim(expected_reference) = ''
    OR expected_reference <> btrim(expected_reference)
    OR expected_version <= 0 THEN
    RETURN FALSE;
  END IF;

  document := convert_from(exact_bytes, 'UTF8')::jsonb;
  IF jsonb_typeof(document) <> 'array'
    OR jsonb_array_length(document) <> 4
    OR document ->> 0 <> 'pirate-operator-managed-root-registry-v1'
    OR document ->> 1 <> expected_reference
    OR jsonb_typeof(document -> 2) <> 'number'
    OR document ->> 2 !~ '^[1-9][0-9]*$'
    OR (document ->> 2)::numeric <> expected_version
    OR jsonb_typeof(document -> 3) <> 'array'
    OR jsonb_array_length(document -> 3) > 256 THEN
    RETURN FALSE;
  END IF;

  entries := document -> 3;
  SELECT COUNT(*) INTO invalid_entries
    FROM jsonb_array_elements(entries) AS item(entry)
   WHERE jsonb_typeof(entry) <> 'array'
      OR jsonb_array_length(entry) <> 3
      OR entry ->> 0 <> 'hns'
      OR is_community_route_root_label('hns', entry ->> 1) IS NOT TRUE
      OR entry ->> 2 <> 'active';
  IF invalid_entries <> 0 THEN
    RETURN FALSE;
  END IF;

  SELECT COALESCE(
           '[' || string_agg(
             format(
               '[%s,%s,%s]',
               to_jsonb(entry ->> 0)::TEXT,
               to_jsonb(entry ->> 1)::TEXT,
               to_jsonb(entry ->> 2)::TEXT
             ),
             ',' ORDER BY ordinal
           ) || ']',
           '[]'
         )
    INTO canonical_entries
    FROM jsonb_array_elements(entries) WITH ORDINALITY AS item(entry, ordinal);
  canonical_document := format(
    '[%s,%s,%s,%s]',
    to_jsonb(document ->> 0)::TEXT,
    to_jsonb(document ->> 1)::TEXT,
    expected_version::TEXT,
    canonical_entries
  );
  IF convert_from(exact_bytes, 'UTF8') <> canonical_document THEN
    RETURN FALSE;
  END IF;

  SELECT COUNT(*) INTO reordered_entries
    FROM (
      SELECT entry ->> 1 AS root_label,
             lag(entry ->> 1) OVER (ORDER BY ordinal) AS previous_root
        FROM jsonb_array_elements(entries) WITH ORDINALITY AS item(entry, ordinal)
    ) AS ordered
   WHERE previous_root IS NOT NULL
     AND convert_to(previous_root, 'UTF8') >= convert_to(root_label, 'UTF8');
  RETURN reordered_entries = 0;
EXCEPTION WHEN OTHERS THEN
  RETURN FALSE;
END;
$_$;

CREATE FUNCTION operator_managed_registry_has_active_root(expected_reference text, expected_version bigint, expected_digest text, expected_root text) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  SELECT EXISTS (
    SELECT 1
      FROM operator_managed_root_registry_versions AS registry
      CROSS JOIN LATERAL jsonb_array_elements(
        convert_from(registry.registry_bytes, 'UTF8')::jsonb -> 3
      ) AS item(entry)
     WHERE registry.registry_reference = expected_reference
       AND registry.registry_version = expected_version
       AND registry.registry_digest = expected_digest
       AND item.entry = jsonb_build_array('hns', expected_root, 'active')
  )
$$;

CREATE FUNCTION populate_media_persona_lineage() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_TABLE_NAME = 'media_submission_command_replays' THEN
    IF NEW.submission_author_persona_id IS NULL THEN
      SELECT submission.author_persona_id INTO NEW.submission_author_persona_id
        FROM media_post_submissions AS submission
       WHERE submission.community_id = NEW.community_id
         AND submission.actor_user_id = NEW.submission_actor_user_id
         AND submission.submission_id = NEW.submission_id
         AND submission.operation_id = NEW.operation_id;
    END IF;
  ELSE
    IF NEW.author_persona_id IS NULL THEN
      SELECT submission.author_persona_id INTO NEW.author_persona_id
        FROM media_post_submissions AS submission
       WHERE submission.community_id = NEW.community_id
         AND submission.actor_user_id = NEW.actor_user_id
         AND submission.submission_id = NEW.submission_id
         AND submission.operation_id = NEW.operation_id;
    END IF;
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION prepare_hns_control_observer_operation_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  configuration_record hns_control_observer_configurations%ROWTYPE;
BEGIN
  IF NEW.snapshot_reference IS NOT NULL THEN
    RAISE EXCEPTION 'HNS observer snapshot reference is database-generated';
  END IF;

  SELECT * INTO configuration_record
    FROM hns_control_observer_configurations
   WHERE provider_configuration_reference = NEW.provider_configuration_reference
     AND provider_configuration_version = NEW.provider_configuration_version;
  IF NOT FOUND
    OR configuration_record.provider_configuration_digest <> NEW.provider_configuration_digest
    OR configuration_record.configuration_bytes IS DISTINCT FROM NEW.configuration_bytes THEN
    RAISE EXCEPTION 'HNS observer operation configuration authority mismatch';
  END IF;

  NEW.snapshot_reference := 'hns-observer:postgres:' || gen_random_uuid()::text;
  RETURN NEW;
END;
$$;

CREATE FUNCTION prevent_persona_create_action_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE EXCEPTION 'persona create action is append-only';
END
$$;

CREATE FUNCTION prevent_persona_identity_rewrite() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'persona identity cannot be deleted';
  END IF;
  IF NEW.persona_id IS DISTINCT FROM OLD.persona_id
     OR NEW.account_id IS DISTINCT FROM OLD.account_id
     OR NEW.is_first_persona IS DISTINCT FROM OLD.is_first_persona THEN
    RAISE EXCEPTION 'persona identity is immutable';
  END IF;
  IF OLD.status = 'retired' AND NEW IS DISTINCT FROM OLD THEN
    RAISE EXCEPTION 'retired persona is immutable';
  END IF;
  RETURN NEW;
END
$$;

